    "Tip: notify のカテゴリには短縮名が使えます。eq, tsu, st, nt, lgob, vc でそれぞれ earthquake, tsunami, seismicText, nankaiTrough, lgObservation, volcano を指定できます。",
    "Tip: eewlog fields で、EEWログに記録するフィールドの一覧とON/OFF状態を確認できます。",
